"use client";
// +feature: backlog:item-form

import { useState, useCallback, useMemo, useRef, useEffect } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Link } from "@/lib/nav";
import { useBacklogService } from "@/lib/hooks/useBacklogService";
import type { BacklogItem, BacklogItemInput, AcCriterion, AcCriterionStatus, PipelineMode } from "@/lib/hooks/useBacklogService";
import { useFeatureFlag } from "@/lib/contexts/FeatureFlagsContext";
import { RepoPathInput } from "@/components/ui/RepoPathInput";
import { RadioGroup } from "@/components/ui/RadioGroup";
import type { RadioGroupOption } from "@/components/ui/RadioGroup";
import { radioBtn, radioBtnActive } from "@/components/ui/RadioGroup.css";
import { isGitHubRef } from "@/lib/github/urlParser";
import { useGitHubEnterpriseHosts } from "@/lib/hooks/useGitHubEnterpriseHosts";
import { useBacklogImageAttachment } from "@/lib/hooks/useBacklogImageAttachment";
import { routes } from "@/lib/routes";
import { BACKLOG_CATEGORIES, CATEGORY_DEFAULTS } from "@/lib/backlog/categoryDefaults";
import * as styles from "./BacklogItemForm.css";
import * as markdownStyles from "./markdownBody.css";

// The 9 content-template fields on PipelineMode — used to detect whether the
// selected mode's rendered content depends on {{repo_path}} (G-1).
const CONTENT_TEMPLATE_KEYS = [
  "statusCommandTemplate",
  "doneCommandTemplate",
  "failCommandTemplate",
  "reviewCommandTemplate",
  "shipCommandTemplate",
  "helpCommandTemplate",
  "triagePromptTemplate",
  "reviewPromptTemplate",
  "initialPromptTemplate",
] as const;

const DEFAULT_PIPELINE_MODE_OPTION: RadioGroupOption<string> = {
  value: "",
  label: "Default",
  description: "Built-in default pipeline",
  dataTestId: "backlog-pipeline-mode-default",
};

const PIPELINE_MODE_FETCH_ERROR_NOTICE =
  "Couldn't load pipeline modes — you can still save with Default.";

const PIPELINE_MODE_UNKNOWN_HINT =
  "This item references a pipeline mode that no longer exists or is disabled. Choosing a different mode below will replace it when you save.";

// Slug of the seeded SDD pipeline mode (session.DefaultSDDPipelineModeSlug on
// the backend) and the feature flag name (server/services/feature_flag_service.go's
// sddDefaultPipelineFlagName) gating whether a brand-new item pre-selects it.
// See project_plans/backlog-sdd-default-pipeline — this pre-selection is a
// default, not a lock: the user can still pick any other mode before saving.
const SDD_PIPELINE_MODE_SLUG = "sdd";
const SDD_DEFAULT_PIPELINE_FLAG = "backlog:sdd-default-pipeline";

const UNCATEGORIZED_OPTION: RadioGroupOption<string> = {
  value: "",
  label: "Uncategorized",
  description: "No automation defaults applied — set overrides manually below.",
  dataTestId: "backlog-category-uncategorized",
};

interface BacklogItemFormProps {
  initialValues?: Partial<BacklogItem>;
  onSubmit: (data: BacklogItemInput) => Promise<void>;
  onCancel: () => void;
  isLoading?: boolean;
  /** Repo path inferred by the intent parser; shows a dismissible "suggested" chip while repoPath still equals it. */
  autoSuggestedRepoPath?: string;
}

interface FormErrors {
  title?: string;
  repoPath?: string;
  acCriteria?: string;
  costBudgetThreshold?: string;
}

const AC_STATUS_OPTIONS: { value: AcCriterionStatus; label: string }[] = [
  { value: "pending", label: "Pending" },
  { value: "in_progress", label: "In Progress" },
  { value: "done", label: "Done" },
];

export function BacklogItemForm({
  initialValues,
  onSubmit,
  onCancel,
  isLoading = false,
  autoSuggestedRepoPath,
}: BacklogItemFormProps) {
  const [title, setTitle] = useState(initialValues?.title ?? "");
  const [description, setDescription] = useState(initialValues?.description ?? "");
  const [repoPath, setRepoPath] = useState(initialValues?.repoPath ?? "");
  const [suggestionDismissed, setSuggestionDismissed] = useState(false);
  const [priority, setPriority] = useState<number>(initialValues?.priority ?? 3);
  const [skipPlanning, setSkipPlanning] = useState(initialValues?.skipPlanning ?? false);
  const [skipReviewGate, setSkipReviewGate] = useState(initialValues?.skipReviewGate ?? false);
  const [autoSpawnSession, setAutoSpawnSession] = useState(initialValues?.autoSpawnSession ?? false);
  const [autoCreatePR, setAutoCreatePR] = useState(initialValues?.autoCreatePR ?? false);
  const [autoApprovePlan, setAutoApprovePlan] = useState(initialValues?.autoApprovePlan ?? false);
  const [acCriteria, setAcCriteria] = useState<AcCriterion[]>(
    initialValues?.acCriteria ?? []
  );
  const [pipelineMode, setPipelineMode] = useState(initialValues?.pipelineMode ?? "");
  const [category, setCategory] = useState(initialValues?.category ?? "");
  const [costBudgetThreshold, setCostBudgetThreshold] = useState(
    initialValues?.costBudgetThresholdUsd !== undefined ? String(initialValues.costBudgetThresholdUsd) : ""
  );
  // Same presence-gating rationale as categoryTouchedRef above: only send
  // cost_budget_threshold_usd on an existing item's Update when the operator
  // actually touched this session's input, so a possibly-stale
  // initialValues.costBudgetThresholdUsd never overwrites the item's real
  // stored threshold with itself (a no-op resend is harmless, but resending a
  // stale value is not).
  const costBudgetThresholdTouchedRef = useRef(false);
  // Guards the one-shot SDD default pre-selection below from ever re-firing
  // after either the user has manually touched the selector, or the
  // pre-selection has already applied once — see handlePipelineModeChange
  // and the effect below.
  const pipelineModeTouchedRef = useRef(!!initialValues?.id);
  // Edit-mode-only guard against submitting a stale `category` (see
  // handleCategoryChange and handleSubmit below): initialValues.category can
  // lag the item's real, server-side category if the caller passed a
  // not-yet-reconciled snapshot (BacklogItemDetail.tsx's `item` can be
  // populated from the shared live-item store before its own authoritative
  // fetch resolves). Only an explicit click on the category selector — never
  // this state's initial mount value — sets this true.
  const categoryTouchedRef = useRef(false);
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [descriptionTab, setDescriptionTab] = useState<"write" | "preview">("write");
  const descriptionRef = useRef<HTMLTextAreaElement>(null);
  const {
    error: attachmentError,
    uploading,
    onFileInputChange: handleFileInputChange,
    onPaste: handleDescriptionPaste,
  } = useBacklogImageAttachment({
    textareaRef: descriptionRef,
    setValue: setDescription,
  });
  const fileInputRef = useRef<HTMLInputElement>(null);

  const { listPipelineModes } = useBacklogService();
  const [availableModes, setAvailableModes] = useState<PipelineMode[]>([]);
  const [modesLoading, setModesLoading] = useState(true);
  const [modesError, setModesError] = useState(false);

  // Story 3.2.1 / G-4 / G-3: fetch enabled pipeline modes on mount. While
  // pending or on failure, the RadioGroup below falls back to only the
  // hardcoded "Default" option — never blocking the form.
  useEffect(() => {
    let cancelled = false;
    setModesLoading(true);
    setModesError(false);
    listPipelineModes()
      .then((modes) => {
        if (cancelled) return;
        setAvailableModes(modes.filter((m) => m.enabled));
      })
      .catch(() => {
        if (cancelled) return;
        setModesError(true);
      })
      .finally(() => {
        if (!cancelled) setModesLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [listPipelineModes]);

  // Pre-select the seeded "sdd" pipeline mode for a brand-new item once the
  // operator has opted in via the backlog:sdd-default-pipeline feature flag
  // (see project_plans/backlog-sdd-default-pipeline). This is purely a
  // default: pipelineModeTouchedRef.current stays false only until this
  // effect fires or the user picks a value themselves (handlePipelineModeChange
  // below), whichever happens first — after that, this effect never touches
  // pipelineMode again, so it can never fight a manual choice, and it never
  // runs at all for an existing item (pipelineModeTouchedRef starts true
  // whenever initialValues?.id is set).
  const sddDefaultFlagEnabled = useFeatureFlag(SDD_DEFAULT_PIPELINE_FLAG);
  useEffect(() => {
    if (pipelineModeTouchedRef.current) return;
    if (modesLoading || modesError) return;
    if (!sddDefaultFlagEnabled) return;
    if (!availableModes.some((m) => m.slug === SDD_PIPELINE_MODE_SLUG)) return;
    pipelineModeTouchedRef.current = true;
    setPipelineMode(SDD_PIPELINE_MODE_SLUG);
  }, [sddDefaultFlagEnabled, modesLoading, modesError, availableModes]);

  const handlePipelineModeChange = useCallback((value: string) => {
    pipelineModeTouchedRef.current = true;
    setPipelineMode(value);
  }, []);

  const categoryOptions = useMemo<RadioGroupOption<string>[]>(
    () => [
      UNCATEGORIZED_OPTION,
      ...BACKLOG_CATEGORIES.map((c) => ({
        value: c.value,
        label: c.label,
        description: c.description,
        dataTestId: `backlog-category-${c.value}`,
      })),
    ],
    []
  );

  const categoryHintForValue = useCallback(
    (v: string) => categoryOptions.find((o) => o.value === v)?.description,
    [categoryOptions]
  );

  // Applies a category's automation-toggle defaults to local form state.
  // Deliberately scoped to CREATE mode only (initialValues?.id unset) — this
  // is a one-time "apply template" action fired at category-selection time,
  // never a persistent binding: every field it touches remains a normal,
  // fully-editable control afterward, and any later manual change to that
  // field always wins over what this handler set. Re-selecting a category
  // (including switching between two categories) re-applies that category's
  // defaults from scratch each time — deliberately chosen over "don't
  // clobber a field the user already touched" for predictability: picking a
  // category always shows exactly that category's defaults, with no
  // per-field history to reason about. On an existing item (edit mode) this
  // only ever updates the `category` label itself — the automation toggles
  // are intentionally left untouched.
  const handleCategoryChange = useCallback(
    (value: string) => {
      categoryTouchedRef.current = true;
      setCategory(value);
      if (initialValues?.id) return;
      const defaults = CATEGORY_DEFAULTS[value];
      if (!defaults) return;
      setSkipReviewGate(defaults.skipReviewGate);
      setSkipPlanning(defaults.skipPlanning);
      setAutoSpawnSession(defaults.autoSpawnSession);
      setAutoCreatePR(defaults.autoCreatePR);
      setAutoApprovePlan(defaults.autoApprovePlan);
      pipelineModeTouchedRef.current = true;
      setPipelineMode(defaults.pipelineMode);
    },
    [initialValues?.id]
  );

  // Options offered by the RadioGroup: "Default" is always first and always
  // present. While the fetch is pending or failed, no other options render —
  // this alone satisfies G-4/G-3's "only Default selectable" requirement.
  const pipelineModeOptions = useMemo<RadioGroupOption<string>[]>(() => {
    if (modesLoading || modesError) {
      return [DEFAULT_PIPELINE_MODE_OPTION];
    }
    return [
      DEFAULT_PIPELINE_MODE_OPTION,
      ...availableModes.map((m) => ({
        value: m.slug,
        label: m.name,
        description: m.description || undefined,
        dataTestId: `backlog-pipeline-mode-${m.slug}`,
      })),
    ];
  }, [modesLoading, modesError, availableModes]);

  // The fetch succeeded but no enabled modes exist yet — distinct from
  // loading/error: without this, a picker with nothing to pick from looks
  // identical to a picker that's broken or hasn't fetched at all (the exact
  // "single greyed Default button, clicking it does nothing" confusion
  // flagged in docs/tasks/backlog-feature-improvement.md's 2026-07-19 audit).
  const hasNoAvailableModes = !modesLoading && !modesError && availableModes.length === 0;

  // G-2: an item's stored pipelineMode may reference a mode that's since been
  // deleted or disabled. Only evaluate once the fetch has actually succeeded —
  // during loading/error we can't yet tell "unresolvable" apart from
  // "haven't checked yet".
  const unresolvedPipelineMode = useMemo(() => {
    if (modesLoading || modesError) return null;
    if (!pipelineMode) return null;
    if (pipelineModeOptions.some((o) => o.value === pipelineMode)) return null;
    return pipelineMode;
  }, [modesLoading, modesError, pipelineMode, pipelineModeOptions]);

  const pipelineModeHintForValue = useCallback(
    (v: string) => {
      if (unresolvedPipelineMode && v === unresolvedPipelineMode) {
        return PIPELINE_MODE_UNKNOWN_HINT;
      }
      return pipelineModeOptions.find((o) => o.value === v)?.description;
    },
    [unresolvedPipelineMode, pipelineModeOptions]
  );

  const unresolvedPipelineModeOption = unresolvedPipelineMode ? (
    <button
      type="button"
      role="radio"
      aria-checked="true"
      aria-disabled="true"
      disabled
      tabIndex={-1}
      className={[radioBtn, radioBtnActive].join(" ")}
      data-testid={`backlog-pipeline-mode-unknown-${unresolvedPipelineMode}`}
    >
      {`Unknown mode ('${unresolvedPipelineMode}')`}
    </button>
  ) : undefined;

  // G-1: the selected mode's own content-template fields may assume a
  // repo path is present. Non-blocking — warns, never disables.
  const selectedPipelineMode = useMemo(
    () => availableModes.find((m) => m.slug === pipelineMode) ?? null,
    [availableModes, pipelineMode]
  );
  const selectedModeRequiresRepoPath = useMemo(() => {
    if (!selectedPipelineMode) return false;
    return CONTENT_TEMPLATE_KEYS.some((key) => selectedPipelineMode[key]?.includes("{{repo_path}}"));
  }, [selectedPipelineMode]);
  const showRepoPathPrerequisiteWarning = selectedModeRequiresRepoPath && !repoPath.trim();

  const validate = useCallback((): FormErrors => {
    const errs: FormErrors = {};
    if (!title.trim()) {
      errs.title = "Title is required.";
    }
    if (!initialValues?.id && !repoPath.trim()) {
      errs.repoPath = "Repository path is required for automated triage.";
    }
    const trimmedThreshold = costBudgetThreshold.trim();
    if (trimmedThreshold !== "") {
      const parsed = Number(trimmedThreshold);
      if (isNaN(parsed) || parsed < 0) {
        errs.costBudgetThreshold = "Budget threshold must be zero or greater.";
      }
    }
    return errs;
  }, [title, repoPath, initialValues?.id, costBudgetThreshold]);

  const handleSubmit = useCallback(
    async (e: React.FormEvent) => {
      e.preventDefault();
      const errs = validate();
      if (Object.keys(errs).length > 0) {
        setErrors(errs);
        return;
      }
      setErrors({});
      setSubmitting(true);
      try {
        // Evaluate vagueness before submitting: short description + no AC = vague
        const descriptionText = description.trim();
        const isVague = descriptionText.length < 80 && acCriteria.length === 0;
        // On an existing item, only send `category` if the user actually
        // touched the selector this session. `category`'s local state is
        // seeded once from initialValues.category at mount, which can be
        // stale (see categoryTouchedRef's comment above); omitting an
        // untouched field lets the server's presence-gated partial-update
        // semantics (session.v1.UpdateBacklogItemRequest.category is an
        // `optional string`) leave the item's real, already-stored category
        // — and thus whatever automation profile it implies — untouched,
        // instead of silently overwriting it with a possibly-wrong value on
        // every save. Create mode has no existing value to protect, so it
        // always sends the current selection (including "" for
        // Uncategorized).
        const categoryForSubmit =
          !initialValues?.id || categoryTouchedRef.current ? category : undefined;
        // Same "only send if touched (or creating)" gating as categoryForSubmit
        // above — see costBudgetThresholdTouchedRef's comment. An empty input
        // is sent as `undefined` (omitted from the request), which the server
        // treats as "leave the existing threshold untouched," not "clear it" —
        // this control cannot yet clear an already-configured threshold back
        // to unset, only set or change it (same limitation reworkCapOverride's
        // single-pointer-presence convention already has for its own sentinel
        // value).
        const trimmedThreshold = costBudgetThreshold.trim();
        const parsedThreshold = trimmedThreshold === "" ? undefined : Number(trimmedThreshold);
        const costBudgetThresholdForSubmit =
          !initialValues?.id || costBudgetThresholdTouchedRef.current ? parsedThreshold : undefined;
        await onSubmit({
          title: title.trim(),
          description: descriptionText || undefined,
          repoPath: repoPath.trim(),
          priority,
          skipPlanning,
          skipReviewGate,
          autoSpawnSession,
          autoCreatePR,
          autoApprovePlan,
          acCriteria: acCriteria.map((c, i) => ({ ...c, index: i })),
          skipTriage: isVague,
          pipelineMode,
          category: categoryForSubmit,
          costBudgetThresholdUsd: costBudgetThresholdForSubmit,
        });
      } finally {
        setSubmitting(false);
      }
    },
    [
      title,
      description,
      repoPath,
      priority,
      skipPlanning,
      skipReviewGate,
      autoSpawnSession,
      autoCreatePR,
      autoApprovePlan,
      acCriteria,
      pipelineMode,
      category,
      costBudgetThreshold,
      initialValues?.id,
      onSubmit,
      validate,
    ]
  );

  const addCriterion = useCallback(() => {
    setAcCriteria((prev) => [
      ...prev,
      { index: prev.length, text: "", status: "pending" as AcCriterionStatus },
    ]);
  }, []);

  const removeCriterion = useCallback((index: number) => {
    setAcCriteria((prev) => prev.filter((_, i) => i !== index).map((c, i) => ({ ...c, index: i })));
  }, []);

  const updateCriterionText = useCallback((index: number, text: string) => {
    setAcCriteria((prev) =>
      prev.map((c, i) => (i === index ? { ...c, text } : c))
    );
  }, []);

  const updateCriterionStatus = useCallback((index: number, status: AcCriterionStatus) => {
    setAcCriteria((prev) =>
      prev.map((c, i) => (i === index ? { ...c, status } : c))
    );
  }, []);

  const busy = submitting || isLoading;
  const { hosts: enterpriseHosts } = useGitHubEnterpriseHosts();
  const isCloningRepo = useMemo(
    () => isGitHubRef(repoPath, enterpriseHosts),
    [repoPath, enterpriseHosts]
  );

  return (
    <form
      className={styles.form}
      onSubmit={handleSubmit}
      aria-label="Backlog item form"
      noValidate
      data-testid="backlog-item-form"
    >
      {/* Title */}
      <div className={styles.fieldGroup}>
        <label htmlFor="backlog-title" className={styles.label}>
          Title <span className={styles.required} aria-hidden="true">*</span>
        </label>
        <input
          id="backlog-title"
          type="text"
          className={styles.input}
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="What needs to be done?"
          required
          aria-required="true"
          aria-invalid={!!errors.title}
          aria-describedby={errors.title ? "backlog-title-error" : undefined}
          disabled={busy}
          data-testid="backlog-title-input"
        />
        {errors.title && (
          <span id="backlog-title-error" className={styles.errorMessage} role="alert">
            {errors.title}
          </span>
        )}
      </div>

      {/* Description */}
      <div className={styles.fieldGroup}>
        <div className={styles.descriptionHeader}>
          <label htmlFor="backlog-description" className={styles.label}>
            Description
          </label>
          <div className={styles.descriptionToolbar} role="tablist" aria-label="Description mode">
            <button
              type="button"
              role="tab"
              aria-selected={descriptionTab === "write"}
              className={descriptionTab === "write" ? styles.descriptionTabActive : styles.descriptionTab}
              onClick={() => setDescriptionTab("write")}
              data-testid="backlog-description-tab-write"
            >
              Write
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={descriptionTab === "preview"}
              className={descriptionTab === "preview" ? styles.descriptionTabActive : styles.descriptionTab}
              onClick={() => setDescriptionTab("preview")}
              data-testid="backlog-description-tab-preview"
            >
              Preview
            </button>
            <button
              type="button"
              className={styles.attachButton}
              onClick={() => fileInputRef.current?.click()}
              disabled={busy || uploading}
              data-testid="backlog-attach-image"
            >
              {uploading ? "Uploading…" : "📎 Attach image"}
            </button>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              className={styles.hiddenFileInput}
              onChange={handleFileInputChange}
              disabled={busy || uploading}
              aria-label="Attach image"
              data-testid="backlog-attach-image-input"
            />
          </div>
        </div>
        {descriptionTab === "write" ? (
          <textarea
            id="backlog-description"
            ref={descriptionRef}
            className={styles.textarea}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            onPaste={handleDescriptionPaste}
            placeholder="Provide more context (optional). Supports markdown — paste or attach a screenshot."
            disabled={busy}
            data-testid="backlog-description-input"
          />
        ) : (
          <div className={styles.previewBox} data-testid="backlog-description-preview">
            {description.trim() ? (
              <div className={markdownStyles.markdownBody}>
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{description}</ReactMarkdown>
              </div>
            ) : (
              <span className={styles.previewEmpty}>Nothing to preview yet.</span>
            )}
          </div>
        )}
        {attachmentError && (
          <span className={styles.errorMessage} role="alert" data-testid="backlog-attach-image-error">
            {attachmentError}
          </span>
        )}
      </div>

      {/* Repo path + Priority */}
      <div className={styles.twoColumn}>
        <div className={styles.fieldGroup}>
          <label htmlFor="backlog-repo-path" className={styles.label}>
            Repository Path <span className={styles.required} aria-hidden="true">*</span>
          </label>
          <RepoPathInput
            id="backlog-repo-path"
            value={repoPath}
            onChange={setRepoPath}
            placeholder="/home/user/project or https://github.com/owner/repo"
            required
            disabled={busy}
            error={errors.repoPath}
            hint="Local path to your clone, or a GitHub URL — we'll clone it for you."
            detectGitHubUrl
            data-testid="backlog-repo-path-input"
          />
          {autoSuggestedRepoPath && !suggestionDismissed && repoPath === autoSuggestedRepoPath && (
            <span className={styles.repoSuggestionChip} data-testid="repo-suggestion-chip">
              Suggested from your sessions
              <button
                type="button"
                className={styles.repoSuggestionDismiss}
                data-testid="repo-suggestion-dismiss"
                aria-label="Dismiss suggested repository"
                disabled={busy}
                onClick={() => {
                  setSuggestionDismissed(true);
                  setRepoPath("");
                  document.getElementById("backlog-repo-path")?.focus();
                }}
              >
                <span aria-hidden="true">✕</span>
              </button>
            </span>
          )}
          {errors.repoPath && (
            <span id="backlog-repo-path-error" className={styles.errorMessage} role="alert">
              {errors.repoPath}
            </span>
          )}
        </div>

        <div className={styles.fieldGroup}>
          <label htmlFor="backlog-priority" className={styles.label}>
            Priority
          </label>
          <select
            id="backlog-priority"
            className={styles.select}
            value={priority}
            onChange={(e) => setPriority(Number(e.target.value))}
            disabled={busy}
            data-testid="backlog-priority-select"
          >
            <option value={1}>P1 — Critical</option>
            <option value={2}>P2 — High</option>
            <option value={3}>P3 — Medium</option>
            <option value={4}>P4 — Low</option>
            <option value={5}>P5 — Trivial</option>
          </select>
        </div>
      </div>

      {/* Category selector — pre-fills automation-toggle defaults on create, and is
          just a label on an existing item (edit mode never touches the toggles). */}
      <div className={styles.fieldGroup}>
        <RadioGroup
          options={categoryOptions}
          value={category}
          onChange={handleCategoryChange}
          groupLabel="Category"
          hintForValue={categoryHintForValue}
        />
      </div>

      {/* Pipeline mode selector (Epic 3.2) */}
      <div className={styles.fieldGroup}>
        <RadioGroup
          options={pipelineModeOptions}
          value={pipelineMode}
          onChange={handlePipelineModeChange}
          groupLabel="Pipeline mode"
          hintForValue={pipelineModeHintForValue}
          trailingContent={unresolvedPipelineModeOption}
        />
        {modesError && (
          <span role="status" className={styles.checkboxHint} data-testid="backlog-pipeline-mode-fetch-error">
            {PIPELINE_MODE_FETCH_ERROR_NOTICE}
          </span>
        )}
        {hasNoAvailableModes && (
          <span className={styles.pipelineModeEmptyHint} data-testid="backlog-pipeline-mode-empty-hint">
            No custom pipeline modes exist yet.{" "}
            <Link href={routes.settingsPipelineModes} className={styles.pipelineModeEmptyHintLink}>
              Create one in Settings →
            </Link>
          </span>
        )}
      </div>

      {/* Per-item soft budget warning threshold (Epic 5.3, design/ux.md Surface D2) */}
      <div className={styles.fieldGroup}>
        <label htmlFor="backlog-cost-budget-threshold" className={styles.label}>
          Budget threshold (USD)
        </label>
        <input
          id="backlog-cost-budget-threshold"
          type="number"
          min="0"
          step="0.01"
          className={styles.input}
          value={costBudgetThreshold}
          onChange={(e) => {
            costBudgetThresholdTouchedRef.current = true;
            setCostBudgetThreshold(e.target.value);
          }}
          placeholder="No threshold configured"
          aria-label="Budget threshold in USD for this item"
          aria-invalid={!!errors.costBudgetThreshold}
          aria-describedby={errors.costBudgetThreshold ? "backlog-cost-budget-threshold-error" : undefined}
          disabled={busy}
          data-testid="backlog-cost-budget-threshold-input"
        />
        <span className={styles.checkboxHint}>
          Show a warning banner on this item once its total cost reaches this amount. Leave blank for no budget tracking.
        </span>
        {errors.costBudgetThreshold && (
          <span id="backlog-cost-budget-threshold-error" className={styles.errorMessage} role="alert">
            {errors.costBudgetThreshold}
          </span>
        )}
      </div>

      {/* Flags */}
      <fieldset className={styles.fieldGroup} data-testid="backlog-overrides-fieldset">
        <legend className={styles.label}>Overrides (independent of pipeline mode)</legend>
        <div className={styles.twoColumn}>
          <div className={styles.fieldGroup}>
            <label className={styles.checkboxRow} htmlFor="backlog-skip-planning">
              <input
                id="backlog-skip-planning"
                type="checkbox"
                className={styles.checkboxInput}
                checked={skipPlanning}
                onChange={(e) => setSkipPlanning(e.target.checked)}
                disabled={busy}
                data-testid="backlog-skip-planning-checkbox"
              />
              <span className={styles.checkboxLabel}>Skip planning phase</span>
            </label>
            <span className={styles.checkboxHint}>
              Go straight to triage without a separate planning pass.
            </span>
          </div>

          <div className={styles.fieldGroup}>
            <label className={styles.checkboxRow} htmlFor="backlog-skip-review">
              <input
                id="backlog-skip-review"
                type="checkbox"
                className={styles.checkboxInput}
                checked={skipReviewGate}
                onChange={(e) => setSkipReviewGate(e.target.checked)}
                disabled={busy}
                data-testid="backlog-skip-review-checkbox"
              />
              <span className={styles.checkboxLabel}>Skip review gate</span>
            </label>
            <span className={styles.checkboxHint}>
              Mark work done without an automated review pass first.
            </span>
          </div>

          <div className={styles.fieldGroup}>
            <label className={styles.checkboxRow} htmlFor="backlog-auto-spawn-session">
              <input
                id="backlog-auto-spawn-session"
                type="checkbox"
                className={styles.checkboxInput}
                checked={autoSpawnSession}
                onChange={(e) => setAutoSpawnSession(e.target.checked)}
                disabled={busy}
                data-testid="backlog-auto-spawn-session-checkbox"
              />
              <span className={styles.checkboxLabel}>Auto-spawn work session</span>
            </label>
            <span className={styles.checkboxHint}>
              Skip the manual &quot;Spawn Session&quot; click — start work automatically once triage marks the item ready.
            </span>
          </div>

          <div className={styles.fieldGroup}>
            <label className={styles.checkboxRow} htmlFor="backlog-auto-create-pr">
              <input
                id="backlog-auto-create-pr"
                type="checkbox"
                className={styles.checkboxInput}
                checked={autoCreatePR}
                onChange={(e) => setAutoCreatePR(e.target.checked)}
                disabled={busy}
                data-testid="backlog-auto-create-pr-checkbox"
              />
              <span className={styles.checkboxLabel}>Auto-create PR on completion</span>
            </label>
            <span className={styles.checkboxHint}>
              Skip the manual Review Queue &quot;Create PR&quot; click — a PR is opened automatically once a work session finishes. The prompt still runs unattended, so review the diff before merging.
            </span>
          </div>

          <div className={styles.fieldGroup}>
            <label className={styles.checkboxRow} htmlFor="backlog-auto-approve-plan">
              <input
                id="backlog-auto-approve-plan"
                type="checkbox"
                className={styles.checkboxInput}
                checked={autoApprovePlan}
                onChange={(e) => setAutoApprovePlan(e.target.checked)}
                disabled={busy}
                data-testid="backlog-auto-approve-plan-checkbox"
              />
              <span className={styles.checkboxLabel}>Auto-approve plan</span>
            </label>
            <span className={styles.checkboxHint}>
              Skip the manual &quot;Approve Plan&quot; click — a plan produced by triage is approved automatically and moves straight to implementation. Review the plan afterward instead of before.
            </span>
          </div>
        </div>
      </fieldset>

      {showRepoPathPrerequisiteWarning && selectedPipelineMode && (
        <span role="alert" className={styles.errorMessage} data-testid="backlog-pipeline-mode-repo-path-warning">
          {`⚠ ${selectedPipelineMode.name} mode requires a repository path — add one above.`}
        </span>
      )}

      {/* Acceptance Criteria */}
      <div className={styles.acSection}>
        <div className={styles.acSectionHeader}>
          <label className={styles.label}>Acceptance Criteria</label>
          <button
            type="button"
            className={styles.addButton}
            onClick={addCriterion}
            disabled={busy}
            aria-label="Add acceptance criterion"
            data-testid="backlog-add-criterion"
          >
            + Add criterion
          </button>
        </div>

        {acCriteria.length > 0 && (
          <div className={styles.acList} role="list" aria-label="Acceptance criteria list">
            {acCriteria.map((criterion, i) => (
              <div key={i} className={styles.acRow} role="listitem">
                <input
                  type="text"
                  className={styles.acInput}
                  value={criterion.text}
                  onChange={(e) => updateCriterionText(i, e.target.value)}
                  placeholder={`Criterion ${i + 1}`}
                  disabled={busy}
                  aria-label={`Criterion ${i + 1} text`}
                  data-testid={`backlog-criterion-text-${i}`}
                />
                <select
                  className={styles.acStatusSelect}
                  value={criterion.status}
                  onChange={(e) => updateCriterionStatus(i, e.target.value as AcCriterionStatus)}
                  disabled={busy}
                  aria-label={`Criterion ${i + 1} status`}
                  data-testid={`backlog-criterion-status-${i}`}
                >
                  {AC_STATUS_OPTIONS.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  className={styles.removeButton}
                  onClick={() => removeCriterion(i)}
                  disabled={busy}
                  aria-label={`Remove criterion ${i + 1}`}
                  data-testid={`backlog-remove-criterion-${i}`}
                >
                  ×
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Form Actions */}
      <div className={styles.formActions}>
        <button
          type="button"
          className={styles.cancelButton}
          onClick={onCancel}
          disabled={busy}
          data-testid="backlog-form-cancel"
        >
          Cancel
        </button>
        <button
          type="submit"
          className={styles.submitButton}
          disabled={busy}
          data-testid="backlog-form-submit"
        >
          {busy
            ? isCloningRepo
              ? "Cloning repository…"
              : "Saving…"
            : initialValues?.id
              ? "Save Changes"
              : "Create Item"}
        </button>
      </div>
    </form>
  );
}
